//! C-alignment regression tests (step 5j: defensive mode, PRAGMA table_info types, EXPLAIN QUERY PLAN rows).
//! GENERATED by target/perf-work/step5j/gen/gen_core_tests.py: every expected line is what the C SQLite
//! 3.54.1 shell prints in list mode for the same statements (an error is reduced to `ERR: <message>`). The C
//! shell runs with SQLITE_DBCONFIG_DEFENSIVE on unless the case says otherwise.
use crate::Connection;
use sqliters_types::Value;

fn render(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Integer(i) => i.to_string(),
        Value::Text(s) => s.split('\0').next().unwrap_or("").to_owned(),
        Value::Blob(b) => String::from_utf8_lossy(b).into_owned(),
        Value::Real(r) => sqliters_types::real_to_text(*r),
    }
}

/// Runs the statements one after the other; a failing statement adds `ERR: message`.
fn run(defensive: bool, stmts: &[&str]) -> Vec<String> {
    let conn = Connection::open_in_memory().unwrap();
    conn.set_defensive(defensive).unwrap();
    let mut out = Vec::new();
    for sql in stmts {
        let mut stmt = match conn.prepare(sql) {
            Ok(s) => s,
            Err(e) => {
                out.push(format!("ERR: {}", e.message));
                continue;
            }
        };
        loop {
            match stmt.step() {
                Ok(crate::StepResult::Row(r)) => {
                    let row = r.values().iter().map(render).collect::<Vec<_>>().join("|");
                    out.extend(row.split('\n').map(str::to_owned));
                }
                Ok(_) => break,
                Err(e) => {
                    out.push(format!("ERR: {}", e.message));
                    break;
                }
            }
        }
        let _ = stmt.finalize();
    }
    out
}

#[test]
fn defensive_refuses_journal_off_schema_version_and_writable_schema() {
    let got = run(
        true,
        &[
            "create table t(a)",
            "pragma journal_mode=off",
            "pragma journal_mode",
            "pragma schema_version=77",
            "pragma schema_version",
            "pragma writable_schema=on",
            "pragma writable_schema",
            "update sqlite_schema set sql='create table t(a,b)' where name='t'",
            "select sql from sqlite_schema where name='t'",
            "delete from sqlite_schema where name='t'",
            "insert into sqlite_schema values('table','q','q',0,'create table q(a)')",
            "create table sqlite_stat9(x)",
            "create table sqlite_sequence2(a)",
            "pragma temp.schema_version=5",
            "pragma temp.schema_version",
            "create temp table tt(a)",
            "update sqlite_temp_schema set name='x'",
            "delete from sqlite_temp_master",
            "drop table sqlite_schema",
            "alter table sqlite_schema add column q",
            "create index ii on sqlite_schema(name)",
            "create trigger tz after insert on sqlite_schema begin select 1; end",
            "select count(*) from sqlite_schema",
        ],
    );
    let want: &[&str] = &[
        "memory",
        "memory",
        "1",
        "0",
        "ERR: table sqlite_master may not be modified",
        "CREATE TABLE t(a)",
        "ERR: table sqlite_master may not be modified",
        "ERR: table sqlite_master may not be modified",
        "ERR: object name reserved for internal use: sqlite_stat9",
        "ERR: object name reserved for internal use: sqlite_sequence2",
        "0",
        "ERR: table sqlite_temp_master may not be modified",
        "ERR: table sqlite_temp_master may not be modified",
        "ERR: table sqlite_master may not be dropped",
        "ERR: table sqlite_master may not be altered",
        "ERR: table sqlite_master may not be indexed",
        "ERR: cannot create trigger on system table",
        "1",
    ];
    assert_eq!(got, want);
}

#[test]
fn defensive_protects_shadow_tables() {
    let got = run(
        true,
        &[
            "create table t(a)",
            "create virtual table f using fts5(x)",
            "create virtual table r using rtree(id,x0,x1)",
            "insert into f values('hello')",
            "insert into f_config values('zz',1)",
            "delete from f_data",
            "insert into r_rowid values(99,1)",
            "update r_node set data=x'00' where nodeno=1",
            "drop table f_data",
            "alter table f_data rename to zz",
            "alter table f_data add column q",
            "create trigger ftr after insert on f_data begin select 1; end",
            "create trigger tx after insert on t begin insert into f_data values(1,x'00'); end",
            "create trigger ty after insert on t begin delete from f_config; end",
            "create table f_content(a)",
            "create table f_docsize(a)",
            "create index f_idx on t(a)",
            "create view f_config2 as select 1",
            "alter table t rename to f_docsize",
            "insert into f_data select * from f_data",
            "select count(*) from f_data",
            "select count(*) from r_rowid",
            "drop table f",
            "select name from sqlite_schema order by 1",
        ],
    );
    let want: &[&str] = &[
        "ERR: table f_config may not be modified",
        "ERR: table f_data may not be modified",
        "ERR: table r_rowid may not be modified",
        "ERR: table r_node may not be modified",
        "ERR: table f_data may not be dropped",
        "ERR: table f_data may not be altered",
        "ERR: table f_data may not be altered",
        "ERR: cannot create triggers on shadow tables",
        "ERR: trigger \"tx\" may not write to shadow table \"f_data\"",
        "ERR: trigger \"ty\" may not write to shadow table \"f_config\"",
        "ERR: object name reserved for internal use: f_content",
        "ERR: object name reserved for internal use: f_docsize",
        "ERR: object name reserved for internal use: f_idx",
        "ERR: there is already another table or index with this name: f_docsize",
        "ERR: table f_data may not be modified",
        "3",
        "0",
        "f_config2",
        "r",
        "r_node",
        "r_parent",
        "r_rowid",
        "t",
    ];
    assert_eq!(got, want);
}

#[test]
fn without_defensive_writable_schema_and_shadow_writes_work() {
    let got = run(
        false,
        &[
            "create table t(a)",
            "create virtual table r using rtree(id,x0,x1)",
            "pragma writable_schema=on",
            "pragma writable_schema",
            "pragma schema_version=77",
            "pragma schema_version",
            "insert into r_rowid values(99,1)",
            "select * from r_rowid",
            "create table sqlite_stat9(x)",
            "create index ii on sqlite_schema(name)",
            "update sqlite_schema set sql='create table t(a,b)' where name='t'",
            "select sql from sqlite_schema where name='t'",
        ],
    );
    let want: &[&str] = &[
        "1",
        "77",
        "99|1",
        "ERR: table sqlite_master may not be indexed",
        "create table t(a,b)",
    ];
    assert_eq!(got, want);
}

#[test]
fn table_info_shows_standard_types_in_canonical_case() {
    let got = run(
        false,
        &[
            "create table t(a integer primary key, b text, c real, d blob, e int, f any, g Integer, h varchar(10), i \"text\", j numeric, k)",
            "pragma table_info(t)",
            "create table u as select a, b, c, d, e, f, g, h from t",
            "select sql from sqlite_schema where name='u'",
        ],
    );
    let want: &[&str] = &[
        "0|a|INTEGER|0||1",
        "1|b|TEXT|0||0",
        "2|c|REAL|0||0",
        "3|d|BLOB|0||0",
        "4|e|INT|0||0",
        "5|f|ANY|0||0",
        "6|g|INTEGER|0||0",
        "7|h|varchar(10)|0||0",
        "8|i|TEXT|0||0",
        "9|j|numeric|0||0",
        "10|k||0||0",
        "CREATE TABLE u(",
        "  a INT,",
        "  b TEXT,",
        "  c REAL,",
        "  d,",
        "  e INT,",
        "  f NUM,",
        "  g INT,",
        "  h TEXT",
        ")",
    ];
    assert_eq!(got, want);
}

#[test]
fn explain_query_plan_returns_no_row_for_statements_without_a_plan() {
    let got = run(
        false,
        &[
            "create table t(a integer primary key, b, c)",
            "create index tb on t(b)",
            "explain query plan create table x(a)",
            "explain query plan insert into t values(1,2,3)",
            "explain query plan pragma table_info(t)",
            "explain query plan begin",
            "explain query plan drop table t",
            "explain query plan create index i2 on t(c)",
            "select 'end'",
        ],
    );
    let want: &[&str] = &["end"];
    assert_eq!(got, want);
}
